import socket,struct,json,pathlib,time
def execute(host,port,paths):
    if not paths:return []
    if any(not p.startswith('/') or '\r' in p or '\n' in p for p in paths):raise ValueError('invalid path')
    with socket.create_connection((host,port),timeout=2) as sock:
        sock.sendall(''.join('GET '+p+' HTTP/1.1\r\nHost: localhost\r\n\r\n' for p in paths).encode('ascii'))
        with sock.makefile('rb') as f:
            out=[]
            for _ in paths:
                status=f.readline(8192)
                if not status.endswith(b'\r\n'):raise EOFError('status truncated')
                parts=status.split();code=int(parts[1]);headers={}
                while True:
                    line=f.readline(8192)
                    if line==b'\r\n':break
                    if not line.endswith(b'\r\n') or b':' not in line:raise ValueError('bad headers')
                    k,v=line.split(b':',1);headers[k.lower()]=v.strip()
                if b'content-length' not in headers:raise ValueError('length required')
                length=int(headers[b'content-length'])
                if not 0<=length<=1048576:raise ValueError('invalid length')
                body=f.read(length)
                if len(body)!=length:raise EOFError('body truncated')
                out.append((code,body))
            return out
```

实现说明：实现execute(host,port,paths)，一次发送按paths顺序拼接的HTTP/1.1 GET请求，在同一连接按顺序解析所有响应，返回(status,body)列表。题目服务端均使用Content-Length，不使用chunked；必须精确读满正文，不把合并到同次recv的第二个响应当成第一个正文。缺失长度、截断头/体拒绝，超时2秒。

原理补充（原题保留）：
HTTP/1.1 pipelining 允许在同一连接上连续发送多个请求而不逐个等待响应，但响应仍按顺序返回，容易出现队头阻塞且现实支持有限。HTTP/2 的多路复用不是同一机制；非幂等请求重试还需处理重复执行风险。

