import socket,struct,json,pathlib,time
def execute(host,port,payload):
    with socket.create_connection((host,port),timeout=2) as sock:
        sock.sendall(('POST /upload HTTP/1.1\r\nHost: localhost\r\nExpect: 100-continue\r\nContent-Length: '+str(len(payload))+'\r\n\r\n').encode())
        with sock.makefile('rb') as f:
            sent=False
            for _ in range(10):
                line=f.readline(8192)
                if not line.endswith(b'\r\n'):raise EOFError('status truncated')
                status=int(line.split()[1]);headers={}
                while True:
                    line=f.readline(8192)
                    if line==b'\r\n':break
                    if not line.endswith(b'\r\n') or b':' not in line:raise ValueError('bad header')
                    k,v=line.split(b':',1);headers[k.lower()]=v.strip()
                if status==101:raise ValueError('upgrade unsupported')
                if status==100:
                    if sent:raise ValueError('duplicate continue')
                    sock.sendall(payload);sent=True;continue
                if status<200:continue
                length=int(headers.get(b'content-length',b'0'))
                if not 0<=length<=1048576:raise ValueError('invalid length')
                data=f.read(length)
                if len(data)!=length:raise EOFError('body truncated')
                return status,data
            raise ValueError('too many interim responses')
```

