    if len(data)<12:raise ValueError('short header')
    rid,flags,qd,an,ns,ar=struct.unpack('!HHHHHH',data[:12])
    if rid!=ident or not flags&0x8000 or flags&0x020f:raise ValueError('DNS response error')
    def skip(pos):
        seen=set();end=None
        while True:
            if pos>=len(data) or pos in seen:raise ValueError('bad compressed name')
            seen.add(pos);size=data[pos]
            if size&0xc0==0xc0:
                if pos+1>=len(data):raise ValueError('short pointer')
                if end is None:end=pos+2
                pos=((size&0x3f)<<8)|data[pos+1];continue
            if size&0xc0:raise ValueError('bad label')
            pos+=1
            if size==0:return end if end is not None else pos
            if pos+size>len(data):raise ValueError('short label')
            pos+=size
    offset=12
    for _ in range(qd):
        offset=skip(offset)+4
        if offset>len(data):raise ValueError('short question')
    out=[]
    for _ in range(an):
        offset=skip(offset)
        if offset+10>len(data):raise ValueError('short resource record')
        kind,cls,ttl,size=struct.unpack('!HHIH',data[offset:offset+10]);offset+=10
        if offset+size>len(data):raise ValueError('short rdata')
        if kind==1 and cls==1:
            if size!=4:raise ValueError('invalid A size')
            out.append(str(ipaddress.IPv4Address(data[offset:offset+4])))
        offset+=size
    return out
